using System;using System.IO;using System.Linq;using System.Xml;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class CalculationStore {
 public static string StorageDirectory=SharedData.Folder("Settings","BeamTools","SpliceDevelopmentHookConfigurations.xml");public static event Action Changed;
 static string Key(LengthConfiguration c){return c.Input.Fc.ToString("R",CultureInfo.InvariantCulture)+"/"+c.GradeSmall+"/"+c.FySmall.ToString("R",CultureInfo.InvariantCulture)+"/"+c.GradeLarge+"/"+c.FyLarge.ToString("R",CultureInfo.InvariantCulture);}
 public static LengthConfiguration Clone(LengthConfiguration c){var d=new XmlDocument();var e=d.CreateElement("Configuration");c.Write(e);return LengthConfiguration.Read(e);}
 public static List<LengthConfiguration> All(){var list=new List<LengthConfiguration>();foreach(int fc in new[]{21,28,35})foreach(int small in new[]{40,60})foreach(int large in new[]{40,60})list.Add(new LengthConfiguration{Name="Built-in FC"+fc+" G"+small+"/G"+large,GradeSmall=small,GradeLarge=large,FySmall=small==40?275:420,FyLarge=large==40?275:420,Input=new LengthInput{Fc=fc,Round=25,Simplified=true}});list.Add(new LengthConfiguration{Name="Sample 27.6MPa / 414MPa",GradeSmall=60,GradeLarge=60,FySmall=414,FyLarge=414,Input=new LengthInput{Fc=27.6,Round=25,Simplified=true}});var saved=Saved();var hidden=Hidden();return list.Where(c=>!hidden.Contains(c.Name)&&!saved.Any(item=>item.Name.Equals(c.Name,StringComparison.OrdinalIgnoreCase))).Concat(saved).ToList();}
 static List<LengthConfiguration> Saved(){string path=Path.Combine(StorageDirectory,"SpliceDevelopmentHookConfigurations.xml");var list=new List<LengthConfiguration>();if(!File.Exists(path))return list;var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4000000}))d.Load(r);if(d.DocumentElement.Name!="CalculationConfigurations")throw new Exception("Invalid saved calculation configurations. Restore the local configuration store from a backup.");foreach(XmlElement e in d.DocumentElement.SelectNodes("Configuration"))list.Add(LengthConfiguration.Read(e));return list;}
 public static LengthConfiguration Resolve(double fc,int gs,double fs,int gl,double fl){var request=new LengthConfiguration{GradeSmall=gs,FySmall=fs,GradeLarge=gl,FyLarge=fl,Input=new LengthInput{Fc=fc}};var found=All().LastOrDefault(c=>Key(c)==Key(request));if(found!=null)return Clone(found);return new LengthConfiguration{Name="Built-in FC"+fc+" fy"+fs+"/"+fl,GradeSmall=gs,FySmall=fs,GradeLarge=gl,FyLarge=fl,Input=new LengthInput{Fc=fc,Round=25,Simplified=true}};}
 static HashSet<string> Hidden(){var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string path=Path.Combine(StorageDirectory,"SpliceDevelopmentHookConfigurations.xml");if(!File.Exists(path))return names;var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4000000}))doc.Load(reader);foreach(XmlElement element in doc.DocumentElement.SelectNodes("Hidden"))names.Add(element.GetAttribute("name"));return names;}
 static void WriteStore(List<LengthConfiguration> list,HashSet<string> hidden){var doc=new XmlDocument();var root=doc.CreateElement("CalculationConfigurations");doc.AppendChild(root);foreach(var item in list){var node=doc.CreateElement("Configuration");item.Write(node);root.AppendChild(node);}foreach(string name in hidden){var node=doc.CreateElement("Hidden");node.SetAttribute("name",name);root.AppendChild(node);}Directory.CreateDirectory(StorageDirectory);string path=Path.Combine(StorageDirectory,"SpliceDevelopmentHookConfigurations.xml"),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{doc.Save(temp);if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static void Save(LengthConfiguration config){config.Validate();var list=Saved();list.RemoveAll(item=>item.Name.Equals(config.Name,StringComparison.OrdinalIgnoreCase));list.Add(Clone(config));var hidden=Hidden();hidden.Remove(config.Name);WriteStore(list,hidden);if(Changed!=null)Changed();}
 public static void Delete(IEnumerable<string> names){var selected=new HashSet<string>(names,StringComparer.OrdinalIgnoreCase);var list=Saved();list.RemoveAll(item=>selected.Contains(item.Name));var hidden=Hidden();foreach(string name in selected)hidden.Add(name);WriteStore(list,hidden);if(Changed!=null)Changed();}
 public static void RestoreBuiltIns(){WriteStore(Saved(),new HashSet<string>(StringComparer.OrdinalIgnoreCase));if(Changed!=null)Changed();}
 public static LengthConfiguration Choose(IWin32Window owner){var list=All();using(var form=new Form{Text="Saved splice, development & hook configurations",Width=780,Height=520,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false}){AppBrand.Apply(form);var box=new ListBox{Dock=DockStyle.Fill,SelectionMode=SelectionMode.MultiExtended,Font=new System.Drawing.Font("Segoe UI",10),HorizontalScrollbar=true};var tools=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true,Padding=new Padding(8)};var open=new Button{Text="Open selected",AutoSize=true};var delete=new Button{Text="Delete selected",AutoSize=true};var restore=new Button{Text="Restore built-ins",AutoSize=true};var close=new Button{Text="Close",AutoSize=true,DialogResult=DialogResult.Cancel};Action refresh=()=>{list=All();box.Items.Clear();foreach(var config in list)box.Items.Add(config.Name+" | fc "+config.Input.Fc+" | fy "+config.FySmall+" / "+config.FyLarge);if(list.Count>0)box.SelectedIndex=0;open.Enabled=delete.Enabled=list.Count>0;};open.Click+=(s,e)=>{if(box.SelectedIndex>=0){form.DialogResult=DialogResult.OK;form.Close();}};delete.Click+=(s,e)=>{var selected=box.SelectedIndices.Cast<int>().Select(index=>list[index].Name).ToList();if(selected.Count==0)return;if(MessageBox.Show(form,"Delete "+selected.Count+" saved configuration(s)? Existing project snapshots remain unchanged.","Delete saved configurations",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;try{Delete(selected);refresh();}catch(Exception error){MessageBox.Show(form,error.Message,"Saved configurations");}};restore.Click+=(s,e)=>{try{RestoreBuiltIns();refresh();}catch(Exception error){MessageBox.Show(form,error.Message,"Saved configurations");}};box.DoubleClick+=(s,e)=>open.PerformClick();tools.Controls.AddRange(new Control[]{open,delete,restore,close});form.Controls.Add(box);form.Controls.Add(tools);form.AcceptButton=open;form.CancelButton=close;refresh();return form.ShowDialog(owner)==DialogResult.OK&&box.SelectedIndex>=0?Clone(list[box.SelectedIndex]):null;}}

}
class SteelSelection {public int Grade;public double Fy;public override string ToString(){return "Grade "+Grade+" ("+Fy+" MPa)";}}
}
